from pathlib import PurePosixPath

from svx.generated_layout import split_python_support


def test_source_index_handles_unicode_newlines_and_form_feed(monkeypatch):
    import ast
    def no_rescanning(*args, **kwargs):
        raise AssertionError('must not rescan the complete source per literal')
    monkeypatch.setattr(ast, 'get_source_segment', no_rescanning)
    path = PurePosixPath('mirrors.py')
    for newline in ('\n', '\r\n', '\r'):
        source = newline.join([
            '# Generated by svx inheritance-gen.',
            'from svx.inheritance import register_contract',
            "register_contract({'\u7c7b#read': {'text': '\u4e2d\u6587\\f'}})",
            '\fregister_contract({"other": {"value": 42}})', '',
        ])
        outputs = split_python_support({path: source})
        support = outputs[PurePosixPath('svx_support/mirrors.py')]
        literals = [ast.literal_eval(node.value) for node in ast.parse(support).body
                    if isinstance(node, ast.Assign)]
        assert literals == [{'\u7c7b#read': {'text': '\u4e2d\u6587\f'}}, {'other': {'value': 42}}]
        compile(outputs[path], 'mirrors.py', 'exec')
        compile(support, 'support.py', 'exec')


def test_literal_contracts_move_but_registration_order_is_preserved(monkeypatch):
    source = '''# Generated by svx inheritance-gen.
from svx.inheritance import register_contract
register_contract({'driver#read': {'parameters': ()}})
class Driver:
    def read(self):
        return 42
'''
    path = PurePosixPath('svx_mirror/drivers.py')
    outputs = split_python_support({path: source})
    core = outputs[path]
    support = outputs[PurePosixPath('svx_support/svx_mirror/drivers.py')]
    assert "'parameters'" not in core
    assert "'parameters'" in support
    assert core.index('register_contract(_svx__driver_read_contract)') < core.index('class Driver:')
    assert 'def register_' not in support
    assert 'return 42' in core
    assert outputs == split_python_support({path: source})
    compile(core, str(path), 'exec')
    compile(support, 'support.py', 'exec')


def test_support_literals_are_reindented_not_aligned_under_long_names():
    import ast
    method_id = 'package/' * 30 + 'Driver#send'
    value = {method_id: {'parameters': (('item', 'input', {'type': 'int'}),), 'response': ()}}
    source = ('# Generated by svx inheritance-gen.\n'
              'from svx.inheritance import register_contract, register_constructor\n'
              f'register_contract({value!r})\n'
              f'register_constructor("driver", {(("seed", {"type": "int"}),)!r})\n')
    path = PurePosixPath('driver.py')
    result = split_python_support({path: source})
    support = result[PurePosixPath('svx_support/driver.py')]
    assignments = [node for node in ast.parse(support).body if isinstance(node, ast.Assign)]
    assert [ast.literal_eval(node.value) for node in assignments] == [value, (('seed', {'type': 'int'}),)]
    assert "\n        'parameters': (\n            ('item', 'input', {" in support
    assert all(len(line) - len(line.lstrip()) <= 16 for line in support.splitlines())
    assert 'register_contract(' not in support and 'register_constructor(' not in support


def test_dynamic_or_nested_registrations_are_not_relocated():
    source = '''# Generated by svx inheritance-gen.
from svx.inheritance import register_contract
register_contract(dynamic_contract)
def load(contract):
    register_contract(contract)
'''
    sources = {PurePosixPath('mirrors.py'): source}
    assert split_python_support(sources) == sources


def test_registration_scope_index_preserves_local_assignments_and_aliases():
    source = '''# Generated by svx inheritance-gen.
from svx.inheritance import register_contract as bind
bind({'top': 1})
def shadowed():
    bind = print
    bind({'local': 2})
def deferred():
    bind({'deferred': 3})
'''
    result = split_python_support({PurePosixPath('mirrors.py'): source})
    core = result[PurePosixPath('mirrors.py')]
    support = result[PurePosixPath('svx_support/mirrors.py')]
    assert "bind({'local': 2})" in core
    assert "'local'" not in support
    assert "'top'" in support and "'deferred'" in support
    compile(core, 'mirrors.py', 'exec')


def test_support_scope_index_does_not_rescan_module_assignments_per_call(monkeypatch):
    import ast
    original = ast.walk
    assignments = 0
    def observed(node):
        nonlocal assignments
        if isinstance(node, ast.Assign):
            assignments += 1
        return original(node)
    monkeypatch.setattr(ast, 'walk', observed)
    source = ('# Generated by svx inheritance-gen.\n'
              'from svx.inheritance import register_contract\n'
              + ''.join(f'value_{i} = {i}\n' for i in range(80))
              + ''.join(f'register_contract({{{str(i)!r}: {i}}})\n' for i in range(80)))
    result = split_python_support({PurePosixPath('mirrors.py'): source})
    assert assignments == 80
    assert len(ast.parse(result[PurePosixPath('svx_support/mirrors.py')]).body) == 80


def test_constructor_literal_metadata_moves_without_moving_construction():
    source = '''# Generated by svx inheritance-gen.
from svx.inheritance import register_constructor as bind_constructor
bind_constructor('sv://drivers/Driver', (('seed', {'type': 'int'}),), external_targets=('item',))
class Driver:
    def __init__(self, seed):
        self.seed = seed
'''
    path = PurePosixPath('svx_mirror/drivers.py')
    outputs = split_python_support({path: source})
    assert "external_targets=_svx__drivers_Driver_external_targets" in outputs[path]
    assert 'self.seed = seed' in outputs[path]
    support = outputs[PurePosixPath('svx_support/svx_mirror/drivers.py')]
    assert 'register_constructor(' not in support and "drivers_Driver_external_targets = ('item',)" in support
    compile(support, 'support.py', 'exec')


def test_deferred_literal_registration_stays_deferred_and_shadowing_is_preserved():
    source = '''# Generated by svx inheritance-gen.
from svx.inheritance import register_contract
def deferred():
    register_contract({'driver#read': {'parameters': ()}})
def custom(register_contract):
    register_contract({'custom': 1})
'''
    path = PurePosixPath('mirrors.py')
    outputs = split_python_support({path: source})
    assert "'driver#read'" not in outputs[path]
    assert "register_contract({'custom': 1})" in outputs[path]
    assert 'def deferred():\n    from svx_support.mirrors import' in outputs[path]
    compile(outputs[path], str(path), 'exec')


def test_private_record_names_are_readable_and_collision_free():
    from svx.inheritance import _call_record_class_name, _call_record_type_id
    import hashlib
    method = 'sv://drivers_pkg/Driver#read'
    name = _call_record_class_name(method, 'request')
    assert 'drivers' in name and 'Driver' in name and 'read' in name
    assert name.endswith('_Request') and name.isidentifier()
    assert _call_record_class_name('a/b', 'request') != _call_record_class_name('a_x2f_b', 'request')
    assert _call_record_type_id(method, 'request') == 'svx.call.'+hashlib.sha256(method.encode()).hexdigest()+'.request'


def test_readable_record_class_name_does_not_change_wire_descriptor():
    import hashlib
    import svtypes
    from svx.inheritance import _call_record_class_name, _call_record_type_id
    method = 'sv://drivers_pkg/Driver#read'
    legacy = 'SVXCall_'+hashlib.sha256(f'{method}:request'.encode()).hexdigest()[:20]+'_Request'
    def record(name):
        return svtypes.RecordSchema(_call_record_type_id(method, 'request'),
            (('value', svtypes.Bit[8]()),), class_name=name).build()
    old = record(legacy)
    new = record(_call_record_class_name(method, 'request'))
    assert svtypes.encoding_descriptor(old).to_dict() == svtypes.encoding_descriptor(new).to_dict()


def test_sv_record_split_preserves_package_position_and_original_core():
    from svx.generated_layout import split_sv_support
    source = '''// Generated by svx inheritance-gen.
package original; typedef bit[7:0] Byte; endpackage
package svx_call_records_pkg;
  import original::*;
  class Request; Byte value; endclass
endpackage : svx_call_records_pkg
package mirror; class Driver; function int read(); return 42; endfunction endclass endpackage
'''
    path = PurePosixPath('units/driver.sv')
    result = split_sv_support({path: source})
    assert 'class Request' not in result[path]
    assert 'class Driver' in result[path]
    assert result[path].index('package original') < result[path].index('`include') < result[path].index('package mirror')
    assert 'class Request' in result[PurePosixPath('support/units/driver_call_records.svh')]


def test_sv_endpoint_keeps_editable_core_and_moves_protocol_methods_together():
    from svx.generated_layout import split_sv_support
    source = '''package bridge;
class SVXExternal_BusEndpoint;
  function int _svx__core_read(); return 7; endfunction
  virtual task _svx__sv_invoke(); endtask
  virtual function void _svx__sv_invoke_function(); endfunction
endclass
endpackage
'''
    path = PurePosixPath('mirrors.sv')
    result = split_sv_support({path: source})
    assert 'return 7;' in result[path]
    assert 'virtual task _svx__sv_invoke' in result[path]
    assert 'virtual function void _svx__sv_invoke_function' in result[path]
    assert list(result) == [path]


