def test_split_accepts_var_qualified_type_expression_declaration():
    from svx.generated_layout import split_sv_support
    source = '''package bridge;
class Driver;
  int value;
  function int _svx__core_read(); return value; endfunction
  virtual function void _svx__sv_invoke();
    var type(value) temporary;
    temporary = value;
  endfunction
endclass
endpackage
'''
    path = PurePosixPath('mirrors.sv')
    result = split_sv_support({path: source})
    assert '_svx__core_read' in result[path]
    assert 'var type(value) temporary;' in result[path]


def test_export_splits_both_static_gateway_and_mirror_dispatch(tmp_path):
    from io import StringIO
    from svx.cli import main
    root = tmp_path/'generated'
    assert main(['export', '--package', 'editable_static_pkg', '--sv-source',
                 'tests/integration/editable_static.sv', '--out', str(root)], out=StringIO()) == 0
    core = (root/'mirrors.sv').read_text(encoding='utf-8')
    assert 'static function void _svx__core_Driver_scale(input chandle request,' in core
    assert 'static function void _svx__core_static_Driver_scale(input chandle request,' in core
    assert 'static function void _svx__core_editable_static_pkg_package_scale(input chandle request,' in core
    assert 'static task _svx__sv_invoke_static(' in core
    supports = '\n'.join(path.read_text(encoding='utf-8') for path in (root/'support').rglob('*.svh'))
    assert '`SVX_INVOKE_CORE(_svx__core_Driver_scale)' in core
    assert '`SVX_INVOKE_CORE(_svx__core_static_Driver_scale)' in core
    assert '`SVX_INVOKE_CORE(_svx__core_editable_static_pkg_package_scale)' in core
    assert '::decode(request);' in core
    assert 'response = rsp.encode();' in core
    operation = core.split('static function void _svx__core_Driver_scale(', 1)[1].split('endfunction', 1)[0]
    assert operation.index('::decode(') < operation.index('rsp.svx_return_value = ') < operation.index('rsp.encode(')
    assert 'byte unsigned' not in operation and 'offset' not in operation
    dispatch = core.split('static task _svx__sv_invoke_static(', 1)[1].split('endtask', 1)[0]
    assert '.unpack(' not in dispatch and '.pack(' not in dispatch
    assert 'svx_payload_to_byte_queue' not in dispatch
    assert '_svx__sv_invoke_static' not in supports
